INSERT INTO DimSecurity (SK_SecurityID, Symbol, Issue, Status, Name, ExchangeID, SK_CompanyID, SharesOutstanding, FirstTrade, FirstTradeOnExchange, Dividend, IsCurrent, BatchID, EffectiveDate, EndDate) WITH SecurityFinal AS (SELECT F.Symbol AS Symbol, CAST(F.IssueType AS TEXT) AS Issue, ST.ST_NAME AS Status, CAST(F.Name AS TEXT) AS Name, CAST(F.ExID AS TEXT) AS ExchangeID, DimCo.SK_CompanyID AS SK_CompanyID, CAST(F.ShOut AS INT) AS SharesOutstanding, CAST(STRPTIME(F.FirstTradeDate, '%Y%m%d') AS DATE) AS FirstTrade, CAST(STRPTIME(F.FirstTradeExchg, '%Y%m%d') AS DATE) AS FirstTradeOnExchange, CAST(ROUND(CAST(F.Dividend AS DOUBLE)) AS INT) AS Dividend, CAST(STRPTIME(F.PTS, '%Y%m%d-%H%M%S') AS DATE) AS EffectiveDate FROM Source.FinwireSEC AS F INNER JOIN DimCompany AS DimCo ON (CASE WHEN NOT TRY_CAST(F.CoNameOrCIK AS BIGINT) IS NULL THEN CAST(DimCo.CompanyID AS TEXT) ELSE DimCo.Name END) = F.CoNameOrCIK INNER JOIN StatusType AS ST ON F.Status = ST.ST_ID WHERE F.RecType = 'SEC' AND STRPTIME(F.PTS, '%Y%m%d-%H%M%S') >= DimCo.EffectiveDate AND STRPTIME(F.PTS, '%Y%m%d-%H%M%S') < DimCo.EndDate) SELECT CAST(ROW_NUMBER() OVER (ORDER BY SecurityFinal.EffectiveDate, SecurityFinal.Symbol) AS INT) AS SK_SecurityID, CAST(Symbol AS TEXT) AS Symbol, CAST(Issue AS TEXT) AS Issue, CAST(Status AS TEXT) AS Status, CAST(Name AS TEXT) AS Name, CAST(ExchangeID AS TEXT) AS ExchangeID, CAST(SK_CompanyID AS INT) AS SK_CompanyID, CAST(SharesOutstanding AS INT) AS SharesOutstanding, CAST(FirstTrade AS DATE) AS FirstTrade, CAST(FirstTradeOnExchange AS DATE) AS FirstTradeOnExchange, CAST(Dividend AS INT) AS Dividend, CAST(CASE WHEN EffectiveDate = MAX(EffectiveDate) OVER (PARTITION BY Symbol) THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCurrent, CAST(1 AS DECIMAL(5)) AS BatchID, CAST(EffectiveDate AS DATE) AS EffectiveDate, CAST(COALESCE(CAST(LEAD(EffectiveDate) OVER (PARTITION BY Symbol ORDER BY EffectiveDate) AS DATE), CAST('9999-12-31' AS DATE)) AS DATE) AS EndDate FROM SecurityFinal ORDER BY Symbol, EffectiveDate;
